import{_ as e,o as t,c as d,ag as o}from"./chunks/framework.CAXxHpAX.js";const u=JSON.parse('{"title":"构建流水线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build-pipeline.md","filePath":"guide/build-pipeline.md","lastUpdated":null}'),s={name:"guide/build-pipeline.md"};function i(n,a,c,r,l,p){return t(),d("div",null,[...a[0]||(a[0]=[o(`<h1 id="构建流水线" tabindex="-1">构建流水线 <a class="header-anchor" href="#构建流水线" aria-label="Permalink to &quot;构建流水线&quot;">​</a></h1><p>Aether 的构建过程从 <code>.ae</code> + <code>.rs</code> 源文件到最终原生应用，共经历 12 个步骤。理解整个流水线有助于排查构建问题和定制构建行为。</p><h2 id="流水线概览" tabindex="-1">流水线概览 <a class="header-anchor" href="#流水线概览" aria-label="Permalink to &quot;流水线概览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>aether.toml + .ae + .rs + themes + i18n + assets</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  1.  加载配置 — 解析 aether.toml             │</span></span>
<span class="line"><span>│  2.  提取 Rust 模块 — 解析所有 .rs 文件      │</span></span>
<span class="line"><span>│  3.  验证绑定 — 检查 onClick 引用是否有效     │</span></span>
<span class="line"><span>│  4.  生成 UniFFI crate                       │</span></span>
<span class="line"><span>│  5.  cargo build — 编译 Rust 到动态库        │</span></span>
<span class="line"><span>│  6.  生成 UniFFI Swift 绑定                  │</span></span>
<span class="line"><span>│  7.  加载 themes / i18n / assets             │</span></span>
<span class="line"><span>│  8.  生成资源 Swift 文件                     │</span></span>
<span class="line"><span>│  9.  生成 Xcode 项目                         │</span></span>
<span class="line"><span>│  10. 生成 SwiftUI 视图文件                   │</span></span>
<span class="line"><span>│  11. 移除 import app（xcodeproj 内不需要）   │</span></span>
<span class="line"><span>│  12. xcodebuild — 最终原生编译               │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>    原生 .app 产物</span></span></code></pre></div><h2 id="各步骤详解" tabindex="-1">各步骤详解 <a class="header-anchor" href="#各步骤详解" aria-label="Permalink to &quot;各步骤详解&quot;">​</a></h2><h3 id="_1-加载配置" tabindex="-1">1. 加载配置 <a class="header-anchor" href="#_1-加载配置" aria-label="Permalink to &quot;1. 加载配置&quot;">​</a></h3><p>解析项目根目录下的 <code>aether.toml</code> 文件，读取应用名称、平台配置、权限声明、主题和国际化等设置。如果配置文件不存在或解析失败，将使用默认值。详见 <a href="/guide/config.html">配置参考</a>。</p><h3 id="_2-提取-rust-模块" tabindex="-1">2. 提取 Rust 模块 <a class="header-anchor" href="#_2-提取-rust-模块" aria-label="Permalink to &quot;2. 提取 Rust 模块&quot;">​</a></h3><p>扫描 <code>src/logic/</code> 目录下的所有 <code>.rs</code> 文件，使用 <a href="https://crates.io/crates/syn" target="_blank" rel="noreferrer">syn</a> 库解析 Rust 语法，提取结构体定义、方法签名和参数信息。这些信息用于后续的绑定验证和代码生成。</p><h3 id="_3-验证绑定" tabindex="-1">3. 验证绑定 <a class="header-anchor" href="#_3-验证绑定" aria-label="Permalink to &quot;3. 验证绑定&quot;">​</a></h3><p>检查 <code>.ae</code> 文件中的所有绑定引用（如 <code>onClick={Home.on_click()}</code>），确认引用的模块名和方法名在对应的 <code>.rs</code> 文件中确实存在。如果验证失败，构建将中止并报告所有错误。</p><h3 id="_4-生成-uniffi-crate" tabindex="-1">4. 生成 UniFFI crate <a class="header-anchor" href="#_4-生成-uniffi-crate" aria-label="Permalink to &quot;4. 生成 UniFFI crate&quot;">​</a></h3><p>根据提取的 Rust 模块信息，在构建输出目录生成一个完整的 UniFFI crate，包含：</p><ul><li><code>Cargo.toml</code> — crate 配置，声明 uniffi 依赖</li><li><code>build.rs</code> — 构建脚本</li><li><code>src/lib.rs</code> — 带 <code>#[uniffi::export]</code> 属性的库文件，将所有 Rust 结构体和方法暴露给原生平台</li></ul><h3 id="_5-cargo-build" tabindex="-1">5. cargo build <a class="header-anchor" href="#_5-cargo-build" aria-label="Permalink to &quot;5. cargo build&quot;">​</a></h3><p>在生成的 UniFFI crate 目录下执行 <code>cargo build</code>，编译 Rust 代码为动态链接库 <code>lib&lt;name&gt;.dylib</code>。使用 <code>--release</code> 参数可进行优化构建。</p><h3 id="_6-生成-uniffi-swift-绑定" tabindex="-1">6. 生成 UniFFI Swift 绑定 <a class="header-anchor" href="#_6-生成-uniffi-swift-绑定" aria-label="Permalink to &quot;6. 生成 UniFFI Swift 绑定&quot;">​</a></h3><p>使用 <code>uniffi-bindgen</code> 工具，从编译好的动态库生成 Swift 语言绑定代码，使 Swift/SwiftUI 可以直接调用 Rust 逻辑。</p><h3 id="_7-加载-themes-i18n-assets" tabindex="-1">7. 加载 themes / i18n / assets <a class="header-anchor" href="#_7-加载-themes-i18n-assets" aria-label="Permalink to &quot;7. 加载 themes / i18n / assets&quot;">​</a></h3><p>加载项目资源文件：</p><ul><li><code>src/themes/</code> — 所有主题配置（<code>.toml</code>）</li><li><code>src/i18n/</code> — 所有语言翻译（<code>.toml</code>）</li><li><code>src/assets/</code> — 所有 SVG 图标资源</li></ul><h3 id="_8-生成资源-swift-文件" tabindex="-1">8. 生成资源 Swift 文件 <a class="header-anchor" href="#_8-生成资源-swift-文件" aria-label="Permalink to &quot;8. 生成资源 Swift 文件&quot;">​</a></h3><p>基于加载的资源，生成一系列 Swift 管理类，包括：</p><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>ThemeManager.swift</code></td><td>主题管理，颜色/字体/间距常量</td></tr><tr><td><code>I18nManager.swift</code></td><td>国际化文本管理</td></tr><tr><td><code>AppAssets.swift</code></td><td>SVG 图标资源引用</td></tr><tr><td><code>SystemUI.swift</code></td><td>系统级 UI 能力（Toast、Dialog）</td></tr><tr><td><code>Navigation.swift</code></td><td>导航路由管理</td></tr><tr><td><code>Storage.swift</code></td><td>本地存储</td></tr><tr><td><code>Device.swift</code></td><td>设备信息</td></tr><tr><td><code>Platform.swift</code></td><td>平台检测</td></tr></tbody></table><h3 id="_9-生成-xcode-项目" tabindex="-1">9. 生成 Xcode 项目 <a class="header-anchor" href="#_9-生成-xcode-项目" aria-label="Permalink to &quot;9. 生成 Xcode 项目&quot;">​</a></h3><p>在构建输出目录生成 <code>.xcodeproj</code> 项目文件，将 UniFFI 绑定、资源 Swift 文件、SwiftUI 视图文件等组织到一个完整的 Xcode 项目中。</p><h3 id="_10-生成-swiftui-视图文件" tabindex="-1">10. 生成 SwiftUI 视图文件 <a class="header-anchor" href="#_10-生成-swiftui-视图文件" aria-label="Permalink to &quot;10. 生成 SwiftUI 视图文件&quot;">​</a></h3><p>将每个 <code>.ae</code> 文件转换为对应的 SwiftUI 视图文件（<code>.swift</code>）。一个 <code>.ae</code> 文件生成一个 <code>.swift</code> 文件，组件 <code>.ae</code> 文件生成可复用的 SwiftUI 组件。</p><h3 id="_11-移除-import-app" tabindex="-1">11. 移除 import app <a class="header-anchor" href="#_11-移除-import-app" aria-label="Permalink to &quot;11. 移除 import app&quot;">​</a></h3><p>在 Xcode 项目中，所有 Swift 文件都属于同一个编译目标，因此不需要 SPM 风格的 <code>import app</code> 语句。此步骤自动扫描并移除多余的 import 声明。</p><h3 id="_12-xcodebuild" tabindex="-1">12. xcodebuild <a class="header-anchor" href="#_12-xcodebuild" aria-label="Permalink to &quot;12. xcodebuild&quot;">​</a></h3><p>最终步骤，调用 <code>xcodebuild</code> 编译完整的原生应用。不同平台使用不同的目标：</p><table tabindex="0"><thead><tr><th>平台</th><th>xcodebuild destination</th></tr></thead><tbody><tr><td>macOS</td><td><code>platform=macOS</code></td></tr><tr><td>iPhone</td><td><code>platform=iOS Simulator,name=iPhone 14</code></td></tr><tr><td>iPad</td><td><code>platform=iOS Simulator,name=iPad (10th generation)</code></td></tr></tbody></table><p>构建成功后，<code>.app</code> 产物位于 <code>DerivedData/Build/Products/</code> 目录中。</p><h2 id="未来后端" tabindex="-1">未来后端 <a class="header-anchor" href="#未来后端" aria-label="Permalink to &quot;未来后端&quot;">​</a></h2><p>当前只有 SwiftUI 后端完整连通。代码库中已存在其他平台后端的代码生成器，但尚未接入构建流水线：</p><table tabindex="0"><thead><tr><th>后端</th><th>模块</th><th>目标</th></tr></thead><tbody><tr><td><code>ComposeGen</code></td><td><code>aether-codegen::compose</code></td><td>Kotlin / Jetpack Compose（Android）</td></tr><tr><td><code>ArkUIGen</code></td><td><code>aether-codegen::arkui</code></td><td>HarmonyOS eTS / ArkUI</td></tr></tbody></table><p>这些后端将逐步接入，届时 <code>aether build --platform android</code> 和 <code>aether build --platform harmony</code> 将直接可用。</p>`,38)])])}const f=e(s,[["render",i]]);export{u as __pageData,f as default};
